export function buildMaintenanceTradesSchedule(startISO = null) {
  return buildScheduleFor(MAINTENANCE_TRADES_MODULES, startISO, MAINTENANCE_TRADES_META.cadenceDays);
}

export function maintenanceTradesProgressSummary(progress = {}) {
  return progressSummaryFor(MAINTENANCE_TRADES_MODULES, progress);
}

export function exportMaintenanceTradesCurriculumMarkdown(startISO = null) {
  return exportCurriculumMarkdownFor({
    meta: MAINTENANCE_TRADES_META,
    modules: buildMaintenanceTradesSchedule(startISO),
    sessionFlow: MAINTENANCE_TRADES_SESSION_FLOW,
  }, startISO);
}

/** Every Scripture reference this course cites, deduped — what the verse gate walks. */
export function maintenanceTradesRefs() {
  const seen = new Set();
  for (const m of MAINTENANCE_TRADES_MODULES) {
    for (const part of String((m.anchor && m.anchor.ref) || '').split(';')) {
      const ref = part.trim();
      if (ref) seen.add(ref);
    }
  }
  for (const part of String((MAINTENANCE_TRADES_META.wordFirst && MAINTENANCE_TRADES_META.wordFirst.ref) || '').split(';')) {
    const ref = part.trim();
    if (ref) seen.add(ref);
  }
  return [...seen];
}

